"""Rock Faller: out/meta.json (rockfaller_assets.py) -> resources/hx/games/rockfaller/Data.hx
usage: rockfaller_data.py <out folder> <Data.hx>
"""
import os, sys, json

OUT, DEST = sys.argv[1], sys.argv[2]
m = json.load(open(os.path.join(OUT, 'meta.json')))
sc = m['score']


def f(v):
    return repr(float(v))


code = '''package rockfaller;

// Generated by .opencode/skills/flash-port/scripts/examples/rockfaller/rockfaller_data.py from the pictures of the
// Arkadeo port and the font of the original gfx.swf: do not edit, run rebuild_assets.sh.
class Data {
	// top left corner of the gems _g0.._g4 of the Foreground (sprites fgGem<i>, cut by its mask)
	public static final FG_GEMS:Array<Array<Int>> = [%s];

	// gfx.Score: advance of the digits 0-9 (Alba 14 px), centre of its text field and baseline of the number, origin of
	// "pts" (Alba 10 px), from the origin of the symbol
	public static final SCORE_ADVANCES:Array<Float> = [%s];
	public static inline var SCORE_CX = %s;
	public static inline var SCORE_BASELINE = %s;
	public static inline var SCORE_PTS_X = %s;
	public static inline var SCORE_PTS_Y = %s;
}
''' % (', '.join('[%d, %d]' % (x, y) for x, y in m['fgGems']), ', '.join(f(a) for a in sc['advances']), f(sc['cx']),
       f(sc['baseline']), f(sc['pts'][0]), f(sc['pts'][1]))

os.makedirs(os.path.dirname(DEST), exist_ok=True)
open(DEST, 'w', newline='\n').write(code)
print('Data.hx: %d fg gems, %d digits' % (len(m['fgGems']), len(sc['advances'])))
